"""Build the offline source-paired spider review player."""
from pathlib import Path
import json
from html import escape
ROOT=Path(__file__).resolve().parent;D=ROOT/'integrated';s=json.loads((D/'shot.json').read_text());c=json.loads((D/'assembly-checks.json').read_text())
css='*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:20px}a{color:inherit}h1{font-size:clamp(32px,7vw,62px);line-height:1.05;margin:22px 0 12px}nav{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.meta{font-size:14px;color:#625b50}.badge{display:inline-block;background:#ef9f3a;padding:4px 9px;font-size:12px;font-weight:700}.player{background:#fffdf7;border:1px solid #d5caba;border-radius:8px;overflow:hidden}video{display:block;width:100%;max-height:65vh;background:#fffdf7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{font:inherit;border:1px solid #aaa18f;background:#fffdf7;color:#171512;border-radius:5px;padding:9px 14px;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;border:1px solid #d5caba;background:#fffdf7;border-radius:6px;overflow:hidden;min-width:0}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair img{width:100%;display:block}figcaption{padding:10px;font-size:13px}summary{cursor:pointer}details{margin:22px 0}footer{margin:28px 0;border-top:1px solid #d5caba;padding-top:16px;font-size:14px}.notice{border-left:4px solid #ef9f3a;background:#fffdf7;padding:12px 16px}@media(max-width:600px){.keys{grid-template-columns:1fr}main{padding:14px}button{font-size:15px}}'
script="const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{})},{once:true});v.load()});"
cards=''.join(f'<figure><div class="pair"><img loading="lazy" src="source-{k:02d}.jpg" alt="Source at {s["frames"][f]["source_time"]:.3f}s"><img loading="lazy" src="key-{k:02d}.png" alt="Assembled spider key {k}"></div><figcaption>Key {k} · source {s["frames"][f]["source_time"]:.3f}s<br>{escape(s["xsheet"][f]["note"])}</figcaption></figure>'for k,f in enumerate(s['keys'],1))
reviews=' · '.join(f'<a href="{p.name}">Independent review {i}</a>'for i,p in enumerate(sorted(D.glob('review-v*.json')),1));src=s['source'];tr=c['trace_fidelity'];fit=c['mask_fit'];badge=s.get('review_badge','ASSEMBLED REVIEW COPY')
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spider · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>{css}</style><body><main><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../moving-drawings.html">Moving drawings</a></nav><h1>Spider across its web.</h1><p class="meta">{s['frame_count']} frames · {s['fps']}fps · {len(s['keys'])} keys · {s['duration']:.3f}s</p><p><span class="badge">{escape(badge)}</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="notice">{escape(s['review_note'])}</p><p class="meta">{escape(s['assembly_summary'])}</p><h2>Eight observed reaches.</h2><p class="meta">Source at left, assembled drawing at right. Each key keeps the original nine-stroke construction.</p><section class="keys">{cards}</section><details><summary>Drawing, footage and checks</summary><p>Quick, Draw! spider key {s['design']['key_id']}. One open uneven body outline and eight leg strokes retain their original point correspondence. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0.</p><p>Archive: <a href="{escape(src['shot_page_url'])}">{escape(src['source_title'])}</a> ({src['source_year']}). Retained clip-relative interval 6.000–9.000s. Archive reports public_domain; the record preserves that report without independent rights verification.</p><p>Camera comes from background-only optical flow. Macro stems and web strands are drawn once. The spider body and endpoints are observed at eight exact source frames; hidden leg identity and planted contact intervals remain unresolved. No procedural walk cycle replaces the source action.</p><p>Trace recall minimum {tr['min_recall']:.4f}; all pieces retained {tr['min_parts_kept']:.4f}. Filled drawing/SAM IoU mean {fit['mean_iou']:.4f}, minimum {fit['min_iou']:.4f}; gate {'passes'if fit['pass'] else 'fails'}. These partial masks do not verify contacts.</p><p><a href="shot.json">Timeline and editable strokes</a> · <a href="source.json">Source record</a> · <a href="correspondence.json">Part correspondence</a> · <a href="assembly-checks.json">Checks</a> · <a href="mask-fit.json">Measured fit</a> · <a href="traced.json">Character trace</a> · <a href="sam/provenance.json">SAM provenance</a> · <a href="sam-audit.jpg">Mask inspection</a> · <a href="design.png">Original doodle</a> · <a href="source-contact-sheet.jpg">Source contact sheet</a> · {reviews}</p><p>Classifier and independent normal-speed playback approval remain unrun. No training ran. This review copy is not an accepted training pair.</p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download source comparison</a></footer></main><script>{script}</script></html>''';(D/'index.html').write_text(page);print(D/'index.html')
